import { BrowserRouter, Route, Routes } from 'react-router-dom';
import { PublicShell } from './components/PublicShell';
import {
  CompetitionDetailPage,
  CompetitionsPage,
  CompetitorDetailPage,
  CompetitorsPage,
  FixtureDetailPage,
  FixturesPage,
  NotFoundPage,
  ParticipantDetailPage,
  ParticipantsPage,
  SeasonDetailPage,
  SeasonsPage,
} from './pages/PublicBrowsePages';

function HeroLogo() {
  return (
    <div className="hero__brand-art" aria-hidden="true">
      <img
        className="hero__logo brand-asset--day"
        src="/brand/statsthegame-mark-light.svg"
        alt=""
      />
      <img
        className="hero__logo brand-asset--night"
        src="/brand/statsthegame-mark-dark.svg"
        alt=""
      />
    </div>
  );
}

function LandingPage() {
  return (
    <>
      <section className="hero" aria-labelledby="page-title">
        <HeroLogo />
        <div className="hero__content">
          <p className="eyebrow">Public T20 cricket record</p>
          <h1 id="page-title">Stat&rsquo;sTheGame</h1>
          <p className="hero__tagline">The game, measured ball by ball.</p>
          <p className="hero__summary">
            An event-driven home for published cricket records, designed to keep every result
            connected to the deliveries behind it.
          </p>
        </div>
      </section>

      <section className="principles" aria-labelledby="principles-title">
        <div className="content-boundary">
          <div className="section-heading">
            <p className="eyebrow">Our standard</p>
            <h2 id="principles-title">Explosive. Exact. Traceable.</h2>
          </div>

          <div className="principles__grid">
            <article>
              <p className="principle-number" aria-hidden="true">
                01
              </p>
              <h3>Event-led</h3>
              <p>Published figures begin with accepted, event-level cricket data.</p>
            </article>
            <article>
              <p className="principle-number" aria-hidden="true">
                02
              </p>
              <h3>Public by design</h3>
              <p>Published cricket records are available without an account.</p>
            </article>
            <article>
              <p className="principle-number" aria-hidden="true">
                03
              </p>
              <h3>Built for evidence</h3>
              <p>Every published result is designed to remain connected to its source.</p>
            </article>
          </div>
        </div>
      </section>
    </>
  );
}

export function PublicApp() {
  return (
    <PublicShell>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/competitions" element={<CompetitionsPage />} />
        <Route path="/competitions/:competitionId" element={<CompetitionDetailPage />} />
        <Route path="/seasons" element={<SeasonsPage />} />
        <Route path="/seasons/:seasonId" element={<SeasonDetailPage />} />
        <Route path="/fixtures" element={<FixturesPage />} />
        <Route path="/fixtures/:fixtureId" element={<FixtureDetailPage />} />
        <Route path="/competitors" element={<CompetitorsPage />} />
        <Route path="/competitors/:competitorId" element={<CompetitorDetailPage />} />
        <Route path="/participants" element={<ParticipantsPage />} />
        <Route path="/participants/:participantId" element={<ParticipantDetailPage />} />
        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </PublicShell>
  );
}

function App() {
  return (
    <BrowserRouter>
      <PublicApp />
    </BrowserRouter>
  );
}

export default App;

import type { ReactNode } from 'react';
import { Link, NavLink } from 'react-router-dom';
import { ThemeToggle } from './ThemeToggle';

interface PublicShellProps {
  children: ReactNode;
}

function BrandWordmark() {
  return (
    <span className="brand-wordmark">
      <img
        className="brand-wordmark__image brand-asset--day"
        src="/brand/statsthegame-wordmark-light.svg"
        alt="Stat'sTheGame"
      />
      <img
        className="brand-wordmark__image brand-asset--night"
        src="/brand/statsthegame-wordmark-dark.svg"
        alt="Stat'sTheGame"
      />
    </span>
  );
}

export function PublicShell({ children }: PublicShellProps) {
  return (
    <div className="public-shell">
      <a className="skip-link" href="#main-content">
        Skip to main content
      </a>

      <header className="site-header">
        <div className="site-header__inner">
          <Link className="brand-link" to="/" aria-label="Stat'sTheGame home">
            <BrandWordmark />
          </Link>
          <nav aria-label="Public records" className="site-navigation">
            <NavLink to="/competitions">Competitions</NavLink>
            <NavLink to="/seasons">Seasons</NavLink>
            <NavLink to="/fixtures">Fixtures</NavLink>
            <NavLink to="/competitors">Competitors</NavLink>
            <NavLink to="/participants">Participants</NavLink>
          </nav>
          <ThemeToggle />
        </div>
      </header>

      <main id="main-content">{children}</main>

      <footer className="site-footer">
        <div className="site-footer__inner">
          <BrandWordmark />
          <p>The game, measured ball by ball.</p>
        </div>
      </footer>
    </div>
  );
}

import type { Session, SupabaseClient, User } from '@supabase/supabase-js';
import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';

type SupabaseAuthClient = Pick<SupabaseClient['auth'], 'getSession' | 'onAuthStateChange'>;

export interface AuthState {
  isLoading: boolean;
  isAuthenticated: boolean;
  session: Session | null;
  identity: User | null;
}

interface AuthProviderProps {
  children: ReactNode;
  client: SupabaseAuthClient;
}

const initialAuthState: AuthState = {
  isLoading: true,
  isAuthenticated: false,
  session: null,
  identity: null,
};

const AuthContext = createContext<AuthState | undefined>(undefined);

function resolveAuthState(session: Session | null): AuthState {
  return {
    isLoading: false,
    isAuthenticated: session !== null,
    session,
    identity: session?.user ?? null,
  };
}

export function AuthProvider({ children, client }: AuthProviderProps) {
  const [authState, setAuthState] = useState<AuthState>(initialAuthState);

  useEffect(() => {
    let isActive = true;
    let receivedAuthEvent = false;
    const initialSession = client.getSession();
    const {
      data: { subscription },
    } = client.onAuthStateChange((_event, session) => {
      receivedAuthEvent = true;

      if (isActive) {
        setAuthState(resolveAuthState(session));
      }
    });

    void initialSession
      .then(({ data }) => {
        if (isActive && !receivedAuthEvent) {
          setAuthState(resolveAuthState(data.session));
        }
      })
      .catch(() => {
        if (isActive && !receivedAuthEvent) {
          setAuthState(resolveAuthState(null));
        }
      });

    return () => {
      isActive = false;
      subscription.unsubscribe();
    };
  }, [client]);

  const value = useMemo(() => authState, [authState]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthState {
  const authState = useContext(AuthContext);

  if (!authState) {
    throw new Error('useAuth must be used within an AuthProvider');
  }

  return authState;
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabasePublishableKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

if (!supabaseUrl || !supabasePublishableKey) {
  throw new Error(
    'VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY are required for frontend authentication.',
