import type { Session, SupabaseClient, User } from '@supabase/supabase-js';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';

type SupabaseAuthClient = Pick<
  SupabaseClient['auth'],
  'getSession' | 'onAuthStateChange' | 'signInWithOAuth' | 'signOut'
>;

export interface AuthState {
  isLoading: boolean;
  isAuthenticated: boolean;
  session: Session | null;
  identity: User | null;
}

interface AuthContextValue extends AuthState {
  signInWithGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
}

interface AuthProviderProps {
  children: ReactNode;
  client: SupabaseAuthClient;
}

const initialAuthState: AuthState = {
  isLoading: true,
  isAuthenticated: false,
  session: null,
  identity: null,
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

function resolveAuthState(session: Session | null): AuthState {
  return {
    isLoading: false,
    isAuthenticated: session !== null,
    session,
    identity: session?.user ?? null,
  };
}

export function AuthProvider({ children, client }: AuthProviderProps) {
  const [authState, setAuthState] = useState<AuthState>(initialAuthState);

  useEffect(() => {
    let isActive = true;
    let receivedAuthEvent = false;
    const initialSession = client.getSession();
    const {
      data: { subscription },
    } = client.onAuthStateChange((_event, session) => {
      receivedAuthEvent = true;

      if (isActive) {
        setAuthState(resolveAuthState(session));
      }
    });

    void initialSession
      .then(({ data }) => {
        if (isActive && !receivedAuthEvent) {
          setAuthState(resolveAuthState(data.session));
        }
      })
      .catch(() => {
        if (isActive && !receivedAuthEvent) {
          setAuthState(resolveAuthState(null));
        }
      });

    return () => {
      isActive = false;
      subscription.unsubscribe();
    };
  }, [client]);

  const signInWithGoogle = useCallback(async () => {
    const { error } = await client.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: `${window.location.origin}/`,
      },
    });

    if (error) {
      throw new Error('Google authentication could not be started.');
    }
  }, [client]);

  const signOut = useCallback(async () => {
    const { error } = await client.signOut();

    if (error) {
      throw new Error('Sign-out could not be completed.');
    }
  }, [client]);

  const value = useMemo(
    () => ({ ...authState, signInWithGoogle, signOut }),
    [authState, signInWithGoogle, signOut],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const authState = useContext(AuthContext);

  if (!authState) {
    throw new Error('useAuth must be used within an AuthProvider');
  }

  return authState;
}

import type { AuthChangeEvent, Session, User } from '@supabase/supabase-js';
import { act, render, screen, waitFor } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { describe, expect, it, vi } from 'vitest';
import { AuthProvider, useAuth } from './AuthProvider';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];
type AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;

function createSession(userId = 'user-123'): Session {
  const user = {
    id: userId,
    aud: 'authenticated',
    role: 'authenticated',
    email: 'person@example.com',
    app_metadata: {},
    user_metadata: {},
    identities: [],
    created_at: '2026-08-09T00:00:00.000Z',
  } satisfies User;

  return {
    access_token: 'current-access-token',
    refresh_token: 'managed-by-supabase',
    expires_in: 3600,
    token_type: 'bearer',
    user,
  };
}

function createDeferredSession() {
  let resolve!: (result: { data: { session: Session | null } }) => void;
  const promise = new Promise<{ data: { session: Session | null } }>((resolvePromise) => {
    resolve = resolvePromise;
  });

  return { promise, resolve };
}

function createAuthClient(sessionRequest: Promise<{ data: { session: Session | null } }>) {
  let listener: AuthStateListener | undefined;
  const unsubscribe = vi.fn();
  const client = {
    getSession: vi.fn(() => sessionRequest),
    onAuthStateChange: vi.fn((nextListener: AuthStateListener) => {
      listener = nextListener;
      return {
        data: {
          subscription: {
            id: 'auth-test-subscription',
            callback: nextListener,
            unsubscribe,
          },
        },
      };
    }),
    signInWithOAuth: vi.fn().mockResolvedValue({
      data: { provider: 'google', url: null },
      error: null,
    }),
    signOut: vi.fn().mockResolvedValue({ error: null }),
  } as unknown as AuthClient;

  return {
    client,
    emit(event: AuthChangeEvent, session: Session | null) {
      listener?.(event, session);
    },
  };
}

function AuthStateProbe() {
  const { identity, isAuthenticated, isLoading, session } = useAuth();

  return (
    <dl>
      <dt>Loading</dt>
      <dd>{String(isLoading)}</dd>
      <dt>Authenticated</dt>
      <dd>{String(isAuthenticated)}</dd>
      <dt>Session token</dt>
      <dd>{session?.access_token ?? 'none'}</dd>
      <dt>Identity</dt>
      <dd>{identity?.id ?? 'none'}</dd>
    </dl>
  );
}

describe('AuthProvider', () => {
  it('begins in a loading state and becomes unauthenticated without an existing session', async () => {
    const deferredSession = createDeferredSession();
    const { client } = createAuthClient(deferredSession.promise);

    render(
      <AuthProvider client={client}>
        <AuthStateProbe />
      </AuthProvider>,
    );

    expect(screen.getByText('Loading').nextElementSibling).toHaveTextContent('true');

    await act(async () => deferredSession.resolve({ data: { session: null } }));

    expect(screen.getByText('Loading').nextElementSibling).toHaveTextContent('false');
    expect(screen.getByText('Authenticated').nextElementSibling).toHaveTextContent('false');
    expect(screen.getByText('Identity').nextElementSibling).toHaveTextContent('none');
  });

  it('exposes the existing authenticated session and identity', async () => {
    const session = createSession();
    const { client } = createAuthClient(Promise.resolve({ data: { session } }));

    render(
      <AuthProvider client={client}>
        <AuthStateProbe />
      </AuthProvider>,
    );

    expect(await screen.findByText('current-access-token')).toBeInTheDocument();
    expect(screen.getByText('Authenticated').nextElementSibling).toHaveTextContent('true');
    expect(screen.getByText('Identity').nextElementSibling).toHaveTextContent('user-123');
  });

  it('updates shared state when Supabase reports sign-in and sign-out changes', async () => {
    const { client, emit } = createAuthClient(Promise.resolve({ data: { session: null } }));

    render(
      <AuthProvider client={client}>
        <AuthStateProbe />
      </AuthProvider>,
    );

    await waitFor(() =>
      expect(screen.getByText('Loading').nextElementSibling).toHaveTextContent('false'),
    );

    act(() => emit('SIGNED_IN', createSession('changed-user')));
    expect(screen.getByText('Identity').nextElementSibling).toHaveTextContent('changed-user');
    expect(screen.getByText('Authenticated').nextElementSibling).toHaveTextContent('true');

    act(() => emit('SIGNED_OUT', null));
    expect(screen.getByText('Identity').nextElementSibling).toHaveTextContent('none');
    expect(screen.getByText('Authenticated').nextElementSibling).toHaveTextContent('false');
  });

  it('exposes managed Google OAuth and sign-out actions', async () => {
    const { client } = createAuthClient(Promise.resolve({ data: { session: null } }));

    function AuthActionsProbe() {
      const { signInWithGoogle, signOut } = useAuth();

      return (
        <>
          <button type="button" onClick={() => void signInWithGoogle()}>
            Authenticate
          </button>
          <button type="button" onClick={() => void signOut()}>
            End session
          </button>
        </>
      );
    }

    render(
      <AuthProvider client={client}>
        <AuthActionsProbe />
      </AuthProvider>,
    );

    screen.getByRole('button', { name: 'Authenticate' }).click();
    screen.getByRole('button', { name: 'End session' }).click();

    await waitFor(() =>
      expect(client.signInWithOAuth).toHaveBeenCalledWith({
        provider: 'google',
        options: { redirectTo: `${window.location.origin}/` },
      }),
    );
    expect(client.signOut).toHaveBeenCalledOnce();
  });
});

# Pages

The public application uses React Router inside the reusable `PublicShell`. Public content remains
available without an account; there is no global authentication gate.

## Public browsing routes

| Resource     | Collection      | Detail                         |
| ------------ | --------------- | ------------------------------ |
| Competitions | `/competitions` | `/competitions/:competitionId` |
| Seasons      | `/seasons`      | `/seasons/:seasonId`           |
| Fixtures     | `/fixtures`     | `/fixtures/:fixtureId`         |
| Competitors  | `/competitors`  | `/competitors/:competitorId`   |
| Participants | `/participants` | `/participants/:participantId` |

These pages call only the handwritten public API through `src/api/public-read.ts`. They do not
read Supabase data, attach identity credentials, or require an authenticated session.

Collection pages preserve the API-supported filters, page size, and cursor in the URL query
string. Every route provides explicit loading and error states; collections also provide an empty
state. Related public records are linked where their identifiers are present in the API response.

## Authentication routes

| Route             | Purpose                                                        |
| ----------------- | -------------------------------------------------------------- |
| `/create-account` | Starts managed Supabase Google OAuth for a new identity.       |
| `/sign-in`        | Starts managed Supabase Google OAuth for an existing identity. |
| `/account`        | Displays the signed-in Supabase identity email when available. |

The authentication routes use only Supabase session identity. They do not create application
profiles or interpret roles, approved-submitter status, administrator permissions, or scoped
grants.

## AI Declaration

The public browsing and authentication route documentation was updated with the assistance of
Codex[GPT-5.6 Sol] and ChatGPT-Web[GPT-5.6 Sol].

# Shared frontend components

Place reusable, presentational, accessible UI components here. Feature-specific components should remain inside the relevant directory under `src/features/`.

`PublicShell` provides the shared public header, main-content target, footer and persisted Day Match/Night Match control. Route-level pages supply only their own main content and must not duplicate the shell.

# Frontend features

Organise user-facing functionality by feature rather than by technical file type. Suggested future feature directories include `auth`, `fixtures`, `submissions`, `statistics`, `datasets`, and `api-consumers`.

