import { expect, test, type Page } from '@playwright/test';

const authStorageKey = 'sb-e2e-auth-token';

async function isolateSupabaseClientLock(page: Page) {
  await page.addInitScript(() => {
    Object.defineProperty(window.navigator, 'locks', {
      configurable: true,
      value: undefined,
    });
  });
}

function createStoredSession() {
  const expiresAt = Math.floor(Date.now() / 1000) + 3600;
  const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64url');
  const payload = Buffer.from(
    JSON.stringify({
      aud: 'authenticated',
      exp: expiresAt,
      sub: 'e2e-user',
    }),
  ).toString('base64url');

  return JSON.stringify({
    access_token: `${header}.${payload}.e2e-signature`,
    refresh_token: 'e2e-refresh-token',
    expires_at: expiresAt,
    expires_in: 3600,
    token_type: 'bearer',
    user: {
      id: 'e2e-user',
      aud: 'authenticated',
      role: 'authenticated',
      email: 'browser@example.com',
      app_metadata: {},
      user_metadata: {},
      identities: [],
      created_at: '2026-08-09T00:00:00.000Z',
    },
  });
}

test('signed-out authentication pages are responsive and keyboard operable', async ({ page }) => {
  await isolateSupabaseClientLock(page);
  await page.goto('/create-account');

  await expect(page.getByRole('heading', { name: 'Create Account' })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Create Account' })).toHaveAttribute(
    'aria-current',
    'page',
  );
  await expect(
    page.getByRole('navigation', { name: 'Account' }).getByRole('link', { name: 'Sign In' }),
  ).toBeVisible();

  const hasHorizontalOverflow = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
  );
  expect(hasHorizontalOverflow).toBe(false);

  await page.goto('/sign-in');
  const googleAction = page.getByRole('button', { name: 'Continue with Google' });
  await googleAction.focus();
  await expect(googleAction).toBeFocused();

  const oauthRequest = page.waitForRequest(
    (request) =>
      request.url().startsWith('https://e2e.supabase.co/auth/v1/authorize') &&
      request.url().includes('provider=google'),
  );
  await page.route('https://e2e.supabase.co/auth/v1/authorize**', async (route) => {
    await route.fulfill({ contentType: 'text/html', body: '<p>Managed OAuth boundary</p>' });
  });

  await page.keyboard.press('Enter');

  expect((await oauthRequest).url()).toContain(encodeURIComponent('http://127.0.0.1:4173/'));
});

test('stored Supabase identity updates navigation and can sign out', async ({ page }) => {
  await isolateSupabaseClientLock(page);
  await page.addInitScript(({ key, value }) => window.localStorage.setItem(key, value), {
    key: authStorageKey,
    value: createStoredSession(),
  });
  await page.route('https://e2e.supabase.co/auth/v1/logout**', async (route) => {
    await route.fulfill({ status: 204 });
  });

  await page.goto('/account');

  await expect(page.getByRole('link', { name: 'Account' })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Sign Out' })).toBeVisible();
  await expect(page.getByText('browser@example.com')).toBeVisible();
  await expect(page.getByRole('link', { name: 'Create Account' })).toHaveCount(0);

  const signOut = page.getByRole('button', { name: 'Sign Out' });
  await signOut.focus();
  await expect(signOut).toBeFocused();
  await page.keyboard.press('Enter');

  await expect(page).toHaveURL('/');
  await expect(page.getByRole('link', { name: 'Create Account' })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Sign In' })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Sign Out' })).toHaveCount(0);
});

import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';

const fixture = {
  fixtureId: 'fixture-1',
  competitionId: 'competition-1',
  seasonId: 'season-1',
  season: '2026',
  matchType: 'T20',
  teamType: 'international',
  gender: 'female',
  ballsPerOver: 6,
  scheduledOvers: 20,
  startDate: '2026-08-09',
  endDate: '2026-08-09',
};

test('anonymous browsing preserves filters, pagination and keyboard navigation', async ({
  page,
}) => {
  const requestedUrls: string[] = [];

  await page.route('**/api/v1/**', async (route) => {
    const requestUrl = route.request().url();
    const url = new URL(requestUrl);
    requestedUrls.push(requestUrl);

    if (url.pathname.endsWith('/fixtures/fixture-1')) {
      await route.fulfill({ json: { data: fixture } });
      return;
    }

    if (url.pathname.endsWith('/fixtures')) {
      await route.fulfill({
        json: {
          data: url.searchParams.has('cursor') ? [] : [fixture],
          pagination: {
            nextCursor: url.searchParams.has('cursor') ? null : 'next-fixture-cursor',
          },
        },
      });
      return;
    }

    if (url.pathname.endsWith('/competitors')) {
      await route.fulfill({
        json: {
          data: [{ competitorId: 'competitor-1', name: 'Wanderers' }],
          pagination: { nextCursor: null },
        },
      });
      return;
    }

    await route.fulfill({
      status: 404,
      json: { error: { code: 'NOT_FOUND', message: 'Not found.' } },
    });
  });

  await page.goto('/fixtures?gender=female&limit=25');

  await expect(page.getByRole('heading', { level: 1, name: 'Fixtures' })).toBeVisible();
  await expect(page.getByLabel('Gender')).toHaveValue('female');
  await expect(page.getByLabel('Records per page')).toHaveValue('25');
  await expect(page).toHaveURL(/\/fixtures\?gender=female&limit=25/);
  await expect(page.getByRole('link', { name: 'T20 fixture' })).toBeVisible({ timeout: 15_000 });
  await expect(page.getByRole('link', { name: /Sign in/i })).toHaveCount(0);

  const accessibilityResults = await new AxeBuilder({ page }).analyze();
  const seriousOrCriticalViolations = accessibilityResults.violations.filter(
    (violation) => violation.impact === 'serious' || violation.impact === 'critical',
  );
  expect(seriousOrCriticalViolations).toEqual([]);

  const nextPage = page.getByRole('link', { name: 'Next page' });
  await nextPage.focus();
  await expect(nextPage).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(page).toHaveURL(/cursor=next-fixture-cursor/);
  await expect(page.getByText('No fixtures found')).toBeVisible();
  expect(requestedUrls.some((url) => url.includes('cursor=next-fixture-cursor'))).toBe(true);

  const competitorsLink = page.getByRole('link', { name: 'Competitors', exact: true });
  await competitorsLink.focus();
  await expect(competitorsLink).toBeFocused();
  await page.keyboard.press('Enter');

  await expect(page.getByRole('heading', { level: 1, name: 'Competitors' })).toBeVisible();
  await expect(page.getByRole('link', { name: 'Wanderers' })).toBeVisible();
  await expect(page).not.toHaveURL(/sign-in/);

  const hasHorizontalOverflow = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
  );
  expect(hasHorizontalOverflow).toBe(false);
});

import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';

test('public and authentication page themes have no serious accessibility violations', async ({
  page,
}) => {
  for (const route of ['/', '/create-account', '/sign-in', '/account']) {
    await page.goto(route);

    for (const theme of ['day', 'night'] as const) {
      await page.evaluate((selectedTheme) => {
        document.documentElement.dataset.theme = selectedTheme;
        document.documentElement.style.colorScheme = selectedTheme === 'night' ? 'dark' : 'light';
      }, theme);

      const results = await new AxeBuilder({ page }).analyze();

      const seriousOrCriticalViolations = results.violations.filter(
        (violation) => violation.impact === 'serious' || violation.impact === 'critical',
      );

      expect(
        seriousOrCriticalViolations,
        `${route} ${theme} theme: ${JSON.stringify(seriousOrCriticalViolations, null, 2)}`,
      ).toEqual([]);
    }
  }
});

